{modal==='visit'&&<div className="consult-layout" key={patient}><aside className="consult-aside"><span className="overline">NUEVA CONSULTA</span><div className="person-cell"><Avatar name={p.name}/><strong>{p.name}</strong></div><p>Completá el registro durante la consulta. Podés guardarlo como borrador.</p><nav aria-label="Secciones de la consulta"><a href="#consult-mediciones">01 · Mediciones</a><a href="#consult-evolucion">02 · Evolución</a><a href="#consult-objetivos">03 · Objetivos</a></nav><div className="consult-info"><ShieldCheck size={20}/><span>Los registros anteriores permanecen en el historial.</span></div></aside><div className="consult-fields"><section id="consult-mediciones" className="consult-section"><span className="overline">PASO 01</span><h3>Mediciones de hoy</h3><p>Registrá solo los valores tomados en esta consulta.</p><div className="form-grid">{field('Fecha de consulta','date','date',today,true)}{field('Peso (kg)','weight','number',last?.weight||70,true)}{field('Talla (cm)','height','number',last?.height||165,true)}{field('Grasa corporal (%)','fat','number',last?.fat||0)}{field('Masa muscular (kg)','muscle','number',last?.muscle||0)}{field('Cintura (cm)','waist','number',last?.waist||0)}{field('Cadera (cm)','hip','number',last?.hip||0)}{data.fields.filter(f=>f.active).map((f,i)=><label key={i}>{f.name} {f.unit&&'('+f.unit+')'}<input name={'custom-'+i}/></label>)}</div><small>El IMC se calcula automáticamente con peso y talla.</small></section><section id="consult-evolucion" className="consult-section"><span className="overline">PASO 02</span><h3>Evolución de la consulta</h3><label>Motivo de consulta<textarea name="reason" placeholder="Motivo del encuentro o seguimiento" required/></label><p>Anotá observaciones y decisiones de seguimiento.</p><label>Notas de evolución y diagnóstico<textarea name="notes" placeholder="¿Qué cambió desde la consulta anterior?" required/></label></section><section id="consult-objetivos" className="consult-section"><span className="overline">PASO 03</span><h3>Próximos objetivos</h3><p>El paciente podrá ver estos objetivos en su portal.</p><label>Objetivos para el próximo control<textarea name="goal" placeholder="Definí acciones concretas y fáciles de recordar" required/></label><label>Plan o indicaciones<textarea name="indications" placeholder="Indicaciones acordadas para el próximo período" required/></label><label className="checkbox"><input name="draft" type="checkbox"/>Guardar como borrador</label></section></div></div>}
{(modal==='turn'||modal==='block'||modal==='reschedule')&&<><div className="form-grid">{field('Fecha','date','date',modal==='reschedule'?editAppointment?.date:week,true)}{field('Hora de inicio','time','time',modal==='reschedule'?editAppointment?.time:'09:00',true)}{field('Duración (minutos)','duration','number',modal==='reschedule'?editAppointment?.duration:45,true)}</div>{modal==='turn'?<><label>Tipo de consulta<select name="type"><option>Control</option><option>Primera consulta</option></select></label><label>Modalidad<select name="mode"><option>Presencial</option><option>Virtual</option></select></label></>:modal==='block'?field('Motivo','reason','text','No disponible',true):null}<div className="notice">No se permiten superposiciones con turnos o bloqueos existentes.</div></>}
